<script setup lang="ts">
import {useAccountingAlerts} from './useAccountingAlerts';
import {computed,ref,watch,onBeforeUnmount} from 'vue';import {useAccountingPermissions} from './permissions';
const props=defineProps<{company:number;type:string;documentId:number;version:number;csrf?:string;unsaved?:boolean}>(),emit=defineEmits(['changed','notice']);const can=useAccountingPermissions();
const data=ref<any>(null),busy=ref(false),error=ref(''),note=ref(''),signedFile=ref<File|null>(null),verified=ref(false),fileKey=ref(0);let generation=0;
const paper=computed(()=>data.value?.workflow_mode==='paper'||data.value?.approval?.workflow_mode==='paper');
const canUpload=computed(()=>paper.value&&can('workflow.upload_signed')&&(data.value?.can_submit||data.value?.approval?.can_upload_signed));
async function upload(){
 if(busy.value||props.unsaved)return;
 if(!signedFile.value||note.value.trim().length<5){error.value='Choose the CEO-signed photo or PDF and enter an explanatory note.';return;}
 busy.value=true;error.value='';try{
  const form=new FormData();form.set('company_id',String(props.company));form.set('note',note.value);form.set('signed_copy',signedFile.value);
  const approval=data.value.can_submit?null:data.value.approval;
  form.set('version',String(approval?.version||props.version));
  if(!approval){form.set('initial','1');form.set('document_id',String(props.documentId));}
  const r=await fetch('/accounting/api/approvals/'+(approval?.id||0)+'/signed-copy',{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':props.csrf||''},body:form});
  const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message);
  signedFile.value=null;verified.value=false;fileKey.value++;note.value='';emit('notice',d.message);await load();emit('changed');
 }catch(e){error.value=(e as Error).message;}finally{busy.value=false;}
}
async function load(){const gen=++generation;if(!can('workflow.view'))return;try{const r=await fetch('/accounting/api/approvals/document?'+new URLSearchParams({company_id:String(props.company),type:props.type,id:String(props.documentId)}),{headers:{Accept:'application/json'}});const d=await r.json();if(!r.ok)throw Error(d.message);if(gen===generation)data.value=d;}catch(e){if(gen===generation)error.value=(e as Error).message;}}
watch(()=>[props.documentId,props.version,props.company],()=>{data.value=null;error.value='';signedFile.value=null;verified.value=false;void load();},{immediate:true});onBeforeUnmount(()=>generation++);
async function act(action:string){if(busy.value||props.unsaved)return;if(paper.value&&['post','approve'].includes(action)&&['head_review','manager_review'].includes(data.value?.approval?.stage)&&!verified.value){error.value='Confirm that you verified the attached CEO-signed copy.';return;}if(note.value.trim().length<5){error.value='Enter an explanatory note (at least five characters).';return;}busy.value=true;error.value='';try{const submit=action==='submit';const r=await fetch('/accounting/api/'+(submit?'approvals/submit':'approvals/'+data.value.approval.id+'/actions'),{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:JSON.stringify(submit?{company_id:props.company,type:props.type,id:props.documentId,version:props.version,note:note.value}:{company_id:props.company,version:data.value.approval.version,action,note:note.value,...(paper.value&&['head_review','manager_review'].includes(data.value?.approval?.stage)?{verified_signed_copy:true}:{})})});const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message);note.value='';emit('notice',d.message);await load();emit('changed');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
useAccountingAlerts(error);
</script>
<template><section v-if="can('workflow.view')&&(data?.enabled||data?.approval||error)" class="ac-approval-panel"><h3>{{paper?'Paper approval & posting':'Approval workflow'}}</h3>
<p v-if="paper" class="muted">Print voucher &rarr; CEO stamp / signature on paper &rarr; Finance attaches signed copy &rarr; Judibas GOC Finance Manager reviews &rarr; Judibas GOC Finance Officer confirms &rarr; Super Admin posts.</p><p v-else class="muted">Finance review &rarr; CEO approval &rarr; Finance verification &rarr; Super Admin posting &rarr; Ledger</p>
<p v-if="error" class="notice admin-error" role="alert">{{error}}</p><p v-if="data?.approval"><span class="ac-badge" :class="data.approval.stage==='posted'?'active':'inactive'">{{data.approval.stage==='posted'?'Posted':'Non-posted'}}</span> <strong>Current stage: {{data.approval.stage_label}}</strong></p><p v-else class="muted">Non-posted draft &mdash; no ledger effect.</p>
<p v-if="unsaved" class="ac-help">Save all changes before printing or submitting this document.</p><p v-if="data?.approval?.separation_notice" class="ac-help">{{data.approval.separation_notice}}</p>
<a v-if="paper&&data?.print_url&&!unsaved" class="button" :href="data.print_url" target="_blank" rel="noopener">Print voucher for CEO signature</a>
<div v-if="data?.approval?.signed_copies?.length" class="ac-signed-copies"><h4>Signed voucher copies</h4><article v-for="copy in data.approval.signed_copies" :key="copy.id"><div><strong>{{copy.original_name}}</strong><small>{{copy.current?'Current submission':'Previous submission'}} &middot; Voucher version {{copy.document_version}} &middot; {{copy.uploaded_name}} &middot; {{new Date(copy.created_at).toLocaleString()}}</small></div><div><a class="button" :href="copy.url" target="_blank" rel="noopener">View signed copy</a><a class="button" :href="copy.url+'&download=1'">Download</a></div></article></div>
<div v-if="canUpload" class="ac-signed-upload"><label>{{data?.approval?.signed_copies?.length?'Replace CEO-signed voucher copy':'CEO-stamped / signed voucher copy'}}<input :key="fileKey" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" :disabled="busy||unsaved" @change="signedFile=($event.target as HTMLInputElement).files?.[0]||null"></label><small>Upload a clear JPG, PNG, WebP or PDF (up to 10 MB). The Finance Head will check the signature, voucher details and amounts.</small></div>
<template v-if="data&&(canUpload||data.can_submit||data.approval?.can_approve||data.approval?.can_return||data.approval?.can_withdraw)">
<label>Approval note<textarea aria-label="Approval note" v-model="note" rows="2" maxlength="2000" :disabled="busy||unsaved" placeholder="Explain your submission, review or decision"></textarea></label>
<label v-if="paper&&data.approval?.can_approve&&['head_review','manager_review'].includes(data.approval.stage)" class="ac-signed-verification"><input v-model="verified" type="checkbox" :disabled="busy||unsaved"><span>I verified the CEO stamp/signature, voucher number, saved version and amounts against the attached signed copy.</span></label>
<div class="ac-voucher-actions"><button v-if="canUpload" type="button" class="button primary" :disabled="busy||unsaved||!signedFile" @click="upload">{{busy?'Uploading...':data?.approval?.stage==='manager_review'?'Replace signed copy & resend for verification':'Attach signed copy & send to Judibas GOC Finance Manager'}}</button><button v-if="data.can_submit&&!paper" type="button" class="button primary" :disabled="busy||unsaved" @click="act('submit')">Submit to Finance</button>
<button v-if="data.approval?.can_approve" type="button" class="button primary" :disabled="busy||unsaved||(paper&&['head_review','manager_review'].includes(data.approval.stage)&&!verified)" @click="act(data.approval.stage==='manager_review'?'post':'approve')">{{busy?'Processing...':data.approval.stage==='manager_review'?'Super Admin: approve & post':data.approval.stage==='head_review'?'Verify & send to Judibas GOC Finance Officer':data.approval.stage==='officer_confirm'?'Confirm & send to Super Admin':'Approve & forward'}}</button><button v-if="data.approval?.can_return" type="button" class="button" :disabled="busy||unsaved" @click="act('return')">Return for correction</button><button v-if="data.approval?.can_withdraw" type="button" class="button" :disabled="busy||unsaved" @click="act('withdraw')">Withdraw</button></div></template>
<details v-if="data?.approval?.events?.length"><summary>Approval history</summary><ol class="ac-approval-history"><li v-for="event in data.approval.events" :key="event.id"><strong>{{event.actor_name}} &mdash; {{({submit:'Submitted',signed_copy_submitted:'Signed copy attached',post:'Verified and posted',return:'Returned for correction',withdraw:'Withdrawn',paper_workflow_enabled:'Paper approval enabled',approve:'Approved'} as Record<string,string>)[event.action]||event.action}}</strong><small>{{new Date(event.created_at).toLocaleString()}}</small><p>{{event.note}}</p></li></ol></details></section></template>
